  '⏰ Hora actual según el bot: ' + horaActual() + '\n\n' +
  'Si necesitas cambiar tu nombre o tu rol, pídeselo a un administrador.\n\n' +
  '9  Volver al menú principal\n\n' +
  '💡 Recomendado: 9 Volver';

const INVALIDO =
  opcionInvalida('Estoy esperando un número del 0 al 8.') + '\n\n' + MENU;

const CANCELADO =
  '✅ Listo, cancelé lo que estabas haciendo.\n' +
  'No guardé ningún dato a medias.\n\n' + MENU;

const SIN_PERMISO_ADMIN =
  '🔒 La sección Administrador es exclusiva para usuarios con rol ADMIN.\n' +
  'Tu rol actual es: ' + c.rol + '.\n' +
  'Si necesitas acceso, solicítalo a un administrador.\n\n' + MENU;

/* Ante un mensaje que no es texto NO se pierde el progreso: se avisa y se
   conserva exactamente la misma pantalla, paso y datos parciales.        */
if (vista === 'NO_TEXTO') {
  return salida(
    '📎 Por ahora solo entiendo mensajes de texto.\n' +
    'No puedo procesar fotos, audios, stickers ni archivos.\n\n' +
    'No te preocupes: seguimos justo donde estábamos.\n' +
    'Escribe tu respuesta como texto, o usa /menu para empezar de nuevo.',
    String(c.pantalla_actual || 'MENU'),
    String(c.paso_actual || '0'),
    leerDatos(c.datos_parciales),
    'TIPO_NO_SOPORTADO');
}

const VISTAS = {
  BIENVENIDA: { m: BIENVENIDA, p: 'MENU', r: 'BIENVENIDA' },
  MENU:       { m: MENU,       p: 'MENU', r: 'MENU' },
  AYUDA:      { m: AYUDA,      p: 'AYUDA', r: 'AYUDA' },
  CONFIG:     { m: CONFIG,     p: 'CONFIG', r: 'CONFIG' },
  INVALIDO:   { m: INVALIDO,   p: 'MENU', r: 'OPCION_INVALIDA' },
  CANCELADO:  { m: CANCELADO,  p: 'MENU', r: 'CANCELADO' },
  SIN_PERMISO_ADMIN: { m: SIN_PERMISO_ADMIN, p: 'MENU', r: 'SIN_PERMISO_ADMIN' }
};

const v = VISTAS[vista] || VISTAS.MENU;
return salida(v.m, v.p, '0', {}, v.r, 'NINGUNA', {});

