/* ============================ ROUTER PRINCIPAL ============================
   Decide a que modulo se envia el mensaje. NUNCA adivina la intencion:
   la decision sale de (pantalla_actual + paso_actual + texto recibido).
   Salidas posibles en $json.destino:
     BASE | AGENDA | TAREAS | RECORDATORIOS | HABITOS | LISTAS | REPORTES | ADMIN
   ========================================================================= */
const c = $input.first().json;
const texto = String(c.texto || '').trim();
const t = texto.toLowerCase();
const rol = String(c.rol || 'USER').toUpperCase();

let pantalla = String(c.pantalla_actual || 'MENU').toUpperCase();
let paso = String(c.paso_actual || '0');
let datos = c.datos_parciales || '{}';
let destino = 'BASE';
let vista = 'MENU';
/* entrada_modulo = true significa "acabo de entrar al módulo desde el menú".
   El módulo debe MOSTRAR su menú, no interpretar el número que se escribió
   para entrar. Sin esta bandera el dígito se consumiría dos veces:
   una para elegir el módulo y otra como opción dentro del módulo.        */
let entradaModulo = false;

const MODULOS = ['AGENDA', 'TAREAS', 'RECORDATORIOS', 'HABITOS', 'LISTAS', 'REPORTES', 'ADMIN'];
const PANTALLAS_BASE = ['MENU', 'AYUDA', 'CONFIG', 'ACCESO_DENEGADO', ''];
const MAPA_MENU = { '0': 'AYUDA', '1': 'AGENDA', '2': 'TAREAS', '3': 'RECORDATORIOS',
                    '4': 'HABITOS', '5': 'LISTAS', '6': 'REPORTES', '7': 'CONFIG', '8': 'ADMIN' };

if (c.tipo !== 'TEXTO' || texto === '') {
  destino = 'BASE'; vista = 'NO_TEXTO';
} else if (t === '/start') {
  destino = 'BASE'; vista = 'BIENVENIDA'; pantalla = 'MENU'; paso = '0'; datos = '{}';
} else if (t === '/menu' || t === 'menu' || t === '/inicio' || t === 'inicio') {
  destino = 'BASE'; vista = 'MENU'; pantalla = 'MENU'; paso = '0'; datos = '{}';
} else if (t === '/cancelar' || t === 'cancelar') {
  destino = 'BASE'; vista = 'CANCELADO'; pantalla = 'MENU'; paso = '0'; datos = '{}';
} else if (t === '/ayuda' || t === '/help' || t === 'ayuda') {
  destino = 'BASE'; vista = 'AYUDA'; pantalla = 'AYUDA'; paso = '0';
} else if (PANTALLAS_BASE.indexOf(pantalla) !== -1) {
  if (texto === '9') {
    destino = 'BASE'; vista = 'MENU'; pantalla = 'MENU'; paso = '0'; datos = '{}';
  } else {
    const d = MAPA_MENU[texto];
    if (!d) {
      destino = 'BASE'; vista = 'INVALIDO'; pantalla = 'MENU'; paso = '0';
    } else if (d === 'AYUDA') {
      destino = 'BASE'; vista = 'AYUDA'; pantalla = 'AYUDA'; paso = '0';
    } else if (d === 'CONFIG') {
      destino = 'BASE'; vista = 'CONFIG'; pantalla = 'CONFIG'; paso = '0';
    } else {
      destino = d; pantalla = d; paso = '0'; datos = '{}'; entradaModulo = true;
    }
  }
} else {
  const raiz = pantalla.split('_')[0];
  if (MODULOS.indexOf(raiz) !== -1) {
    destino = raiz;
  } else {
    destino = 'BASE'; vista = 'MENU'; pantalla = 'MENU'; paso = '0'; datos = '{}';
  }
}

/* Control de permisos por rol: el modulo ADMIN es exclusivo del rol ADMIN. */
if (destino === 'ADMIN' && rol !== 'ADMIN') {
  destino = 'BASE'; vista = 'SIN_PERMISO_ADMIN'; pantalla = 'MENU'; paso = '0';
  datos = '{}'; entradaModulo = false;
}

return [{ json: Object.assign({}, c, {
  texto: texto,
  pantalla_actual: pantalla,
  paso_actual: paso,
  datos_parciales: datos,
  destino: destino,
  vista_base: vista,
  entrada_modulo: entradaModulo
})}];

