    texto: texto ? texto.slice(0, 500) : '',
    tipo: texto ? 'TEXTO' : 'NO_TEXTO',
    recibido_en: timestampCO()
  }});
}

// El offset avanza SIEMPRE que Telegram respondio bien, incluso si el mensaje
// no era de texto: de lo contrario ese update se repetiria eternamente.
st.offset = maxId + 1;
return salidaItems;

/* Recupera el ultimo update_id procesado desde la memoria estatica del workflow.
   n8n persiste $getWorkflowStaticData('global') entre ejecuciones cuando el
   workflow esta ACTIVO. Asi no se reprocesan mensajes ya atendidos.          */
const st = $getWorkflowStaticData('global');
if (typeof st.offset !== 'number' || !isFinite(st.offset)) st.offset = 0;
return [{ json: { offset: st.offset } }];
